import React, { useState } from "react";
import { Badge, Button, Checkbox, Select, SegmentedControl, TextInput } from "@kui/foundations-react";
import { ChevronDownGlyph } from "./icons";
import T from "../kui/tokens";

const MONO = T.mono;

// File-type options for the Friendly "File type" select. These compile to the
// exact same `file_extension_include` param the Raw field edits — "usd*" is the
// common default; "All file types" clears the filter.
const FILE_TYPE_OPTIONS = [
  { value: "usd*", children: "USD (usd/usda/usdc/usdz)" },
  { value: "usd", children: "usd" },
  { value: "usda", children: "usda" },
  { value: "usdc", children: "usdc" },
  { value: "usdz", children: "usdz" },
  { value: "", children: "All file types" },
];

// A single facet checkbox row (drill-down faceting). `dimmed` greys a 0-count
// option that is not itself selected. Checkbox + trailing count Badge.
const FacetRow = ({ label, count, checked, dimmed, onToggle, mono }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 11, padding: "6px 4px" }}>
    <div style={{ flex: 1, minWidth: 0 }}>
      <Checkbox
        checked={!!checked}
        onCheckedChange={onToggle}
        slotLabel={
          <span
            style={{
              fontSize: 15,
              fontFamily: mono ? MONO : undefined,
              color: checked ? T.textPrimary : dimmed ? T.textMuted : "#cfcfd2",
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {label}
          </span>
        }
      />
    </div>
    <Badge color="gray" kind="outline">
      {count}
    </Badge>
  </div>
);

// A section label. Static by default (categorical facet headers); pass
// `onToggle` to make it a collapsible header — it then renders as a button with
// a trailing rotating chevron and an optional `badge` (e.g. an active-filter
// dot shown while collapsed).
const SectionHeader = ({ label, icon, upper, open, onToggle, badge }) => {
  // `upper` marks a TOP-LEVEL rail tab (USD Properties, Physics, …): a raised
  // band + primary text so it reads clearly above the plain nested rows.
  const rowStyle = {
    display: "flex",
    alignItems: "center",
    gap: 8,
    width: "100%",
    padding: "16px 20px",
    background: upper ? T.surfaceRaised : "none",
  };
  const content = (
    <>
      {icon}
      <span
        style={{
          flex: 1,
          textAlign: "left",
          fontSize: upper ? 14.5 : 15,
          fontWeight: upper ? 700 : 500,
          letterSpacing: upper ? ".05em" : undefined,
          textTransform: upper ? "uppercase" : undefined,
          color: upper ? T.textPrimary : "#cfcfd2",
          fontFamily: upper ? undefined : MONO,
        }}
      >
        {label}
      </span>
      {badge}
      {onToggle && (
        <ChevronDownGlyph
          width={14}
          height={14}
          color={upper ? "#cfcfd2" : "#8a8a8e"}
          style={{ transform: open ? "rotate(180deg)" : "rotate(0deg)", transition: "transform .15s" }}
        />
      )}
    </>
  );
  return onToggle ? (
    <button type="button" onClick={onToggle} aria-expanded={open} style={{ ...rowStyle, border: "none", cursor: "pointer" }}>
      {content}
    </button>
  ) : (
    <div style={rowStyle}>{content}</div>
  );
};

// How many facet values are visible initially / added per "Show more" click.
const FACET_PAGE_SIZE = 5;

// One facet's value list: shows the top-5 most common values, a small filter
// input above (when the vocabulary is bigger than one page), and a
// "Show 5 more" button underneath that reveals the next page per click — big
// corpus vocabularies (e.g. 114 object classes) stay skimmable. Checked values
// are always kept visible even when they fall outside the current page, so an
// active filter can't hide from the user.
const FacetValueList = ({ label, options }) => {
  const [visible, setVisible] = useState(FACET_PAGE_SIZE);
  const [query, setQuery] = useState("");
  const q = query.trim().toLowerCase();
  const filtered = q ? options.filter((o) => String(o.value).toLowerCase().includes(q)) : options;
  const shown = filtered.slice(0, visible);
  const shownValues = new Set(shown.map((o) => o.value));
  const pinnedChecked = filtered.filter((o) => o.checked && !shownValues.has(o.value));
  const remaining = filtered.length - shown.length - pinnedChecked.length;
  return (
    <>
      {options.length > FACET_PAGE_SIZE && (
        <div style={{ padding: "2px 4px 8px" }}>
          <TextInput
            size="small"
            value={query}
            placeholder={`Filter ${String(label).toLowerCase()}…`}
            aria-label={`Filter ${label} values`}
            onValueChange={(v) => {
              setQuery(v);
              setVisible(FACET_PAGE_SIZE); // new filter -> back to the first page
            }}
          />
        </div>
      )}
      {shown.map((o) => (
        <FacetRow key={o.value} {...o} />
      ))}
      {pinnedChecked.map((o) => (
        <FacetRow key={o.value} {...o} />
      ))}
      {filtered.length === 0 && (
        <div style={{ padding: "6px 4px", fontSize: 13, color: T.textMuted }}>No values match.</div>
      )}
      {remaining > 0 && (
        <div style={{ padding: "4px 0 2px" }}>
          <Button
            kind="tertiary"
            color="neutral"
            size="tiny"
            onClick={() => setVisible((v) => v + FACET_PAGE_SIZE)}
          >
            Show {Math.min(FACET_PAGE_SIZE, remaining)} more ({remaining})
          </Button>
        </div>
      )}
    </>
  );
};

// Whether any control in the group carries an active filter (drives the
// header dot that keeps set filters visible while the group is collapsed).
const groupActive = (g) =>
  g.controls.some((c) => (c.kind === "facet" ? (c.options || []).some((o) => o.checked) : c.checked));

const FilterRail = ({
  mode = "raw", // "raw" | "friendly" — which editor is shown; both write the same searchParams
  onModeChange, // (mode) => void
  groups, // [{ group, controls }] — catalog-generated rail groups, bound via bindRailControl
  fileType, // { show, value, onChange } — Friendly-only select mapping to file_extension_include
  footer, // ReactNode (the Advanced/raw filters group); manages its own padding
}) => {
  // Raw | Friendly toggle is hidden for now — we show Raw only. The Friendly
  // view and its controls are kept in code; flip this to re-enable the toggle.
  const SHOW_MODE_TOGGLE = false;
  const friendly = SHOW_MODE_TOGGLE && mode === "friendly";
  // Per-group collapse, keyed by group name. Every group starts collapsed
  // (matching the static sections); the active-dot on the header keeps
  // applied filters discoverable while closed.
  const [openMap, setOpenMap] = useState({});
  const isOpen = (g) => openMap[g.group] ?? false;
  const toggleGroup = (g) => setOpenMap((m) => ({ ...m, [g.group]: !isOpen(g) }));
  return (
    <div
      style={{
        flex: "none",
        width: 268,
        background: T.surfaceNav,
        borderRight: `1px solid ${T.border}`,
        overflowY: "auto",
      }}
    >
      {/* Raw | Friendly toggle — pinned so it stays reachable while the rail
          scrolls. Switching modes only changes the editing UI; the underlying
          /search_hybrid params (searchParams) are untouched, so the query is
          identical across a Raw → Friendly → Raw round-trip. Hidden for now. */}
      {SHOW_MODE_TOGGLE && (
        <div
          style={{
            position: "sticky",
            top: 0,
            zIndex: 1,
            background: T.surfaceNav,
            borderBottom: `1px solid ${T.border}`,
            padding: "12px 16px",
          }}
        >
          <SegmentedControl
            size="small"
            value={friendly ? "friendly" : "raw"}
            onValueChange={(v) => onModeChange?.(v)}
            items={[
              { value: "raw", children: "Raw" },
              { value: "friendly", children: "Friendly" },
            ]}
            style={{ width: "100%" }}
          />
        </div>
      )}

      {/* File type select — kept behind the (disabled) Friendly mode toggle. */}
      {friendly && fileType?.show && (
        <div style={{ borderBottom: `1px solid ${T.border}` }}>
          <SectionHeader label="File type" upper />
          <div style={{ padding: "0 16px 16px" }}>
            <Select
              size="small"
              value={fileType.value ?? ""}
              onValueChange={(v) => fileType.onChange?.(v)}
              items={FILE_TYPE_OPTIONS}
            />
          </div>
        </div>
      )}

      {footer}

      {/* Catalog-generated filter groups, BELOW the Advanced-filters group.
          Each group is a collapsible section of controls built from the
          deployment's GET /llm_parse/fields catalog (see buildRailGroups):
          value facets (OR "superset" semantics via
          filter_by_properties_include_any), existence toggles, and >=/<=
          sliders. A dot in a collapsed header signals active filters inside. */}
      {(groups || [])
        .filter((g) => g.controls.length > 0)
        .map((g) => (
          <div key={g.group} style={{ borderTop: `1px solid ${T.border}` }}>
            <SectionHeader
              label={g.group}
              upper
              open={isOpen(g)}
              onToggle={() => toggleGroup(g)}
              badge={
                !isOpen(g) && groupActive(g) ? (
                  <span
                    role="img"
                    aria-label={`${g.group} has active filters`}
                    style={{ width: 7, height: 7, borderRadius: 999, background: T.brand, display: "inline-block" }}
                  />
                ) : null
              }
            />
            {isOpen(g) && (
              <div style={{ display: "flex", flexDirection: "column", padding: "0 0 8px" }}>
                {g.controls.map((c) =>
                  c.kind === "facet" ? (
                    <div key={c.name}>
                      <SectionHeader label={c.label} />
                      <div style={{ display: "flex", flexDirection: "column", padding: "0 16px 16px" }}>
                        <FacetValueList label={c.label} options={c.options} />
                      </div>
                    </div>
                  ) : (
                    <div key={c.name} style={{ padding: "0 16px" }}>
                      <FacetRow mono label={c.label} count={c.count} checked={c.checked} onToggle={c.onToggle} />
                    </div>
                  )
                )}
              </div>
            )}
          </div>
        ))}
    </div>
  );
};

export default FilterRail;
