// Percentage, rate and ETA for an in-flight download.
//
// The bundle response carries Content-Length, so a real percentage is available
// as soon as the body starts. That matters most on a slow link: a 128 MB bundle
// at 0.5 MB/s is four minutes of a byte counter with no end in sight, which
// reads as a hung download rather than a big file.

/** Progress for a transfer. `percent`/`etaSeconds` are null when the total is unknown. */
export function describeProgress({ received = 0, total = null, elapsedMs = 0 } = {}) {
  const seconds = elapsedMs / 1000;
  const rate = seconds > 0 && received > 0 ? received / seconds : 0;
  if (!total || total <= 0) return { percent: null, rate, etaSeconds: null };
  const percent = Math.max(0, Math.min(100, (received / total) * 100));
  const etaSeconds = rate > 0 ? Math.max(0, (total - received) / rate) : null;
  return { percent, rate, etaSeconds };
}

/** "45s" / "4m 12s" / "1h 03m" — coarse on purpose, it is an estimate. */
export function formatDuration(seconds) {
  if (seconds == null || !Number.isFinite(seconds)) return null;
  const s = Math.max(0, Math.round(seconds));
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ${String(s % 60).padStart(2, "0")}s`;
  return `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, "0")}m`;
}
