/**
 * Pagination state for the results grid, read off a /search_hybrid response.
 *
 * The server decides how a query is paged and how deep it can go; the UI only
 * has to carry the cursor forward and say why paging stopped. `has_more` comes
 * from the cursor rather than from `hits.length === limit`, which is not a
 * usable end-of-results signal once the backend filters a page for storage
 * permissions.
 */

export const EMPTY_PAGINATION = {
  cursor: null,
  hasMore: false,
  /** How many results are reachable by paging — `paginable_total`, NOT a corpus count. */
  total: null,
  /** Why paging stopped, when it stopped for a reason other than running out. */
  reason: null,
};

/** Extract the pagination envelope from a v3 search response. */
export function readPagination(data) {
  if (!data || typeof data !== "object") return { ...EMPTY_PAGINATION };
  return {
    cursor: data.next_cursor || null,
    hasMore: Boolean(data.has_more),
    total: Number.isFinite(data.paginable_total) ? data.paginable_total : null,
    reason: data.pagination?.depth_limit_reason || null,
  };
}

const hitId = (hit) => hit?.id || hit?.source?.base_key || null;

/**
 * Append a page to the accumulated results, dropping anything already shown.
 *
 * A cursor walk should not repeat documents, but a deep walk has no snapshot:
 * the crawler keeps indexing, so a document inserted between pages shifts the
 * ones after it and can resurface. Duplicate React keys are a worse failure
 * than a missing result, so dedupe by id and keep the first copy.
 */
export function appendHits(existing, incoming) {
  const merged = [...(existing || [])];
  const seen = new Set(merged.map(hitId).filter(Boolean));
  for (const hit of incoming || []) {
    const id = hitId(hit);
    if (id && seen.has(id)) continue;
    if (id) seen.add(id);
    merged.push(hit);
  }
  return merged;
}

/*
 * Constants mirrored from the backend.
 *
 * These are hardcoded rather than read off the response (a deliberate trade — it
 * keeps this a UI-only change), which means the coupling will not announce itself
 * when it breaks: the UI keeps rendering a stale number and nothing fails. If
 * either backend value moves, update it here; if one starts moving regularly,
 * serve it in the `pagination` envelope instead.
 */

/**
 * Hard ceiling on how deep any search can reach.
 *
 * Mirrors `OPENSEARCH_MAX_RESULT_WINDOW`
 * (services/deepsearch_api/deepsearch_api/search_backend/__init__.py), which in
 * turn mirrors OpenSearch's `index.max_result_window` index setting.
 */
export const MAX_RESULT_WINDOW = 10000;

/**
 * The RRF fusion window a multi-leg query gets when it does not ask for one —
 * i.e. how many hybrid results are reachable at all by default.
 *
 * Mirrors `SearchSettings.pagination_default_window`
 * (services/deepsearch_api/deepsearch_api/search_backend/main.py). **The more
 * likely of the two to drift**: it is a documented Helm value
 * (`ngsearch.microservices.search_rest_api.pagination.default_window`, env
 * `PAGINATION_DEFAULT_WINDOW`) that deployments are invited to tune. Only the
 * labelling goes stale if it does — `paginable_total` is read live — but a
 * deployment on 500 would still see 200 labelled "default" here.
 */
export const DEFAULT_WINDOW = 200;

/** Ceiling the Explorer offers for a custom fusion window. */
export const EXPLORER_MAX_WINDOW_SIZE = 1000;

/** Fusion-window presets, in the order the picker shows them. */
export const WINDOW_SIZE_PRESETS = [100, DEFAULT_WINDOW, 500];

/** Page sizes the Explorer offers (the `limit` request field). */
export const PAGE_SIZE_OPTIONS = [20, 40, 60, 100];

/** Page size used when nothing else is specified. */
export const DEFAULT_PAGE_SIZE = 20;

/** Where the fusion window lives, for anything that has to name it to a user. */
export const WINDOW_SIZE_CONTROL = {
  panel: "Advanced scoring",
  section: "Reciprocal Rank Fusion",
  field: "Window size",
};

/**
 * Snap a page size to one the picker can actually show.
 *
 * `limit` used to be a free 1-10000 number, so shared URLs and saved configs
 * carry values no segment matches. Snapping to the nearest offered size keeps
 * those links working and the control in a defined state, rather than rendering
 * a segmented control with nothing selected.
 */
export function normalizePageSize(value) {
  const n = parseInt(value, 10);
  if (!Number.isFinite(n) || n < 1) return DEFAULT_PAGE_SIZE;
  if (PAGE_SIZE_OPTIONS.includes(n)) return n;
  return PAGE_SIZE_OPTIONS.reduce((best, opt) => (Math.abs(opt - n) < Math.abs(best - n) ? opt : best));
}

/** Hold a custom window inside what the UI is willing to stand behind. */
export function clampWindowSize(value) {
  if (value == null || value === "") return null;
  const n = Math.floor(Number(value));
  if (!Number.isFinite(n) || n < 1) return null;
  return Math.min(n, EXPLORER_MAX_WINDOW_SIZE);
}

/**
 * Pages a window yields at a page size — the number users actually care about,
 * and the one that makes the two controls' interaction visible.
 */
export function reachablePages(windowSize, pageSize = DEFAULT_PAGE_SIZE) {
  const w = windowSize || DEFAULT_WINDOW;
  const size = pageSize || DEFAULT_PAGE_SIZE;
  return Math.max(1, Math.floor(w / size));
}

/**
 * Why a chosen window might be a bad idea — or null when it is fine.
 *
 * Two distinct failures, which is why this is not a single threshold:
 * a window *below* the page size silently yields one page and no "Load more",
 * which reads as broken paging; a window at the top of the range is merely slow,
 * and only really bites with the similarity cutoff on (the dedup sweep is
 * O(window^2), see the plan §2.6).
 */
export function windowSizeWarning(windowSize, pageSize = DEFAULT_PAGE_SIZE) {
  if (!windowSize) return null;
  const size = pageSize || DEFAULT_PAGE_SIZE;

  if (windowSize < size) {
    return `Smaller than the page size (${size}), so results stop after one page.`;
  }
  if (windowSize > Math.max(...WINDOW_SIZE_PRESETS)) {
    return "Large windows slow every query, especially with the similarity cutoff on.";
  }
  return null;
}

/**
 * Why "Load more" is gone, in the user's terms — or null when the results
 * simply ran out, which needs no explanation.
 *
 * Returns the pieces separately rather than one string because the footer shows
 * `summary` inline but hides `detail` and `control` behind an info icon: without
 * this split, either the remedy is missing (today's behaviour — a user hits the
 * fusion window and is told to "narrow the search", never that the limit is
 * raisable) or the footer grows a paragraph nobody asked for.
 *
 * `control` is null when the limit genuinely cannot be raised from the UI. That
 * distinction is the point: naming a control that does not exist is how the old
 * `validation` copy went wrong (it advised raising a page size that had no
 * control at the time).
 */
export function describeDepthLimit(reason, { total = null, pageSize = null } = {}) {
  const reachable = Number.isFinite(total) ? total.toLocaleString() : "results";

  switch (reason) {
    case "rrf_window":
      return {
        summary: `Combined text and image searches can only page through the top ${reachable}. Narrow the search to see different results.`,
        detail:
          "Text and image results are combined in the browser over a fixed candidate window, so only " +
          `the top ${reachable} can be paged through. Raising the window fetches more on every query ` +
          "and is slower — noticeably so with the similarity cutoff on. Changing it restarts the " +
          "search from the first page.",
        control: {
          ...WINDOW_SIZE_CONTROL,
          max: EXPLORER_MAX_WINDOW_SIZE,
          action: "openScoring",
        },
      };
    case "max_offset":
    case "result_window":
      return {
        summary: "Reached the maximum search depth. Narrow the search to see different results.",
        detail:
          `Searches cannot page past ${MAX_RESULT_WINDOW.toLocaleString()} results — a limit of the ` +
          "search index itself, not a setting. Add filters, or make the query more specific, to bring " +
          "what you are looking for higher up.",
        control: null,
      };
    case "collapse":
      return {
        summary: `Searches that hide duplicates stop at ${MAX_RESULT_WINDOW.toLocaleString()} results.`,
        detail:
          "Hiding duplicates requires a paging strategy that cannot go deeper than " +
          `${MAX_RESULT_WINDOW.toLocaleString()} results. Turn off "hide duplicates" to page further, ` +
          "at the cost of seeing repeated assets.",
        control: null,
      };
    case "validation":
      return {
        summary: "Validated searches return a single page.",
        detail:
          "Each result is checked against your query by a vision model, which is too slow to run " +
          "page after page, so validated searches return one page only." +
          (pageSize ? ` Raise the page size (currently ${pageSize}) to validate more at once.` : ""),
        // Only actionable once there is a page-size control to point at.
        control: pageSize
          ? { panel: "Advanced filters", section: "Search settings", field: "Page size", action: "openFilters" }
          : null,
      };
    default:
      return null;
  }
}
