import React from "react";
import { Button, SegmentedControl, Tooltip } from "@kui/foundations-react";
import { FilterGlyph, MosaicGlyph, IndexGlyph } from "./icons";
import InterpretedQueryChips from "./InterpretedQueryChips";
import DepthLimitInfo from "./DepthLimitInfo";
import { DEFAULT_PAGE_SIZE, PAGE_SIZE_OPTIONS } from "../utils/pagination";
import T from "../kui/tokens";

// The bar above the results: filters toggle · N results (green) · removable
// selection chips + Delete all · icon-only Mosaic/Index segmented toggle.
const SegBtn = ({ active, icon, label, onClick }) => (
  <Tooltip slotContent={label} side="bottom">
    <Button
      kind={active ? "primary" : "tertiary"}
      color={active ? "brand" : "neutral"}
      size="tiny"
      aria-label={label}
      onClick={onClick}
      style={{ borderRadius: 5 }}
    >
      {icon}
    </Button>
  </Tooltip>
);

// "Showing X of N results", why N is what it is, and how big a page is — all
// with the view controls, because they answer the same question: how much of
// this am I looking at, and how much can I get? Up here they stay visible
// without scrolling to the end of a long list.
const MetaBar = ({
  filtersOpen,
  onToggleFilters,
  resultCount = 0,
  // How many results paging can actually reach (`paginable_total`), when the
  // server reports it. NOT a corpus count: in a hybrid search only the fusion
  // window is reachable, so "1.2M results" over a 200-document pool would be a
  // promise the paginator cannot keep.
  totalAvailable = null,
  chips = [],
  onClearAll,
  viewMode = "grid",
  onViewModeChange,
  // Why paging is capped (`pagination.depth_limit_reason`). Drives the info icon
  // beside the count, which shows from the first page rather than only once
  // paging stops — "60 of 200" against a corpus of millions is exactly when a
  // user needs to know the 200 is a ceiling, and that it can be raised.
  depthLimitReason = null,
  pageSize = DEFAULT_PAGE_SIZE,
  // Absent = no picker. Changing page size does NOT re-run the search (the
  // server keeps `limit` out of the query fingerprint), so this sits with the
  // readouts rather than with the search settings in the filter rail.
  onPageSizeChange,
  onOpenScoring,
}) => {
  const hasChips = chips.length > 0;
  const showingTotal = Number.isFinite(totalAvailable) && totalAvailable > resultCount;
  return (
    <div
      style={{
        flex: "none",
        display: "flex",
        alignItems: "center",
        gap: "13px",
        padding: "13px 22px",
        borderBottom: `1px solid ${T.border}`,
        flexWrap: "wrap",
      }}
    >
      {/* Filters toggle */}
      <Button kind="tertiary" color="neutral" size="small" onClick={onToggleFilters} style={{ flex: "none" }}>
        <FilterGlyph width={18} height={18} color="var(--text-color-brand)" />
        <span style={{ whiteSpace: "nowrap" }}>{filtersOpen ? "Close filters" : "Show filters"}</span>
      </Button>

      {/* Selection chips */}
      {hasChips && (
        <>
          <span style={{ flex: "none", width: "1px", height: "22px", background: T.borderStrong }} />
          <div style={{ display: "flex", alignItems: "center", gap: "9px", minWidth: 0 }}>
            <InterpretedQueryChips chips={chips} onRemove={(c) => c.onRemove && c.onRemove()} />
            <Button kind="tertiary" color="brand" size="small" onClick={onClearAll} style={{ flex: "none", whiteSpace: "nowrap" }}>
              Delete all
            </Button>
          </div>
        </>
      )}

      <div style={{ flex: 1 }} />

      {/* Result count — loaded so far, the reachable total when known, and an
          info icon for where that total comes from. */}
      {resultCount > 0 && (
        <div
          style={{
            flex: "none",
            display: "inline-flex",
            alignItems: "center",
            gap: 5,
            fontSize: "12.8px",
            color: T.textSecondary,
            whiteSpace: "nowrap",
          }}
        >
          <span>
            Showing{" "}
            <span style={{ color: T.brandText, fontWeight: 700, fontVariantNumeric: "tabular-nums" }}>
              {resultCount.toLocaleString()}
            </span>
            {showingTotal ? (
              <>
                {" of "}
                <span style={{ fontVariantNumeric: "tabular-nums" }}>{totalAvailable.toLocaleString()}</span>
              </>
            ) : null}{" "}
            {resultCount === 1 && !showingTotal ? "result" : "results"}
          </span>
          <DepthLimitInfo
            reason={depthLimitReason}
            total={totalAvailable}
            pageSize={pageSize}
            onOpenScoring={onOpenScoring}
          />
        </div>
      )}

      {/* Page size */}
      {onPageSizeChange && resultCount > 0 && (
        <div style={{ flex: "none", display: "inline-flex", alignItems: "center", gap: 7 }}>
          <span style={{ fontSize: "12.8px", color: T.textMuted, whiteSpace: "nowrap" }}>Per page</span>
          <SegmentedControl
            size="tiny"
            value={String(pageSize)}
            aria-label="Results per page"
            onValueChange={(v) => onPageSizeChange(parseInt(v, 10))}
            items={PAGE_SIZE_OPTIONS.map((n) => ({ value: String(n), children: String(n) }))}
          />
        </div>
      )}

      {/* Layout toggle — icon-only (tooltips on hover) */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          padding: "3px",
          background: T.surfaceRaised,
          border: `1px solid ${T.borderStrong}`,
          borderRadius: "7px",
          gap: "2px",
          flex: "none",
        }}
      >
        <SegBtn
          active={viewMode === "grid"}
          icon={<MosaicGlyph width={14} height={14} />}
          label="Mosaic view"
          onClick={() => onViewModeChange && onViewModeChange("grid")}
        />
        <SegBtn
          active={viewMode === "list"}
          icon={<IndexGlyph width={14} height={14} />}
          label="Index view"
          onClick={() => onViewModeChange && onViewModeChange("list")}
        />
      </div>
    </div>
  );
};

export default MetaBar;
