// Consume a fetch Response body into a Blob without holding the whole payload
// in the JS heap.
//
// The API streams download bundles off disk, so the browser is now the only
// place a full copy lives. Pushing every chunk into one array kept the entire
// archive on the JS heap until the Blob was built, which puts a multi-GB bundle
// within reach of an out-of-memory tab crash. Folding chunks into Blob parts as
// they arrive keeps at most one window on the heap and hands the rest to the
// browser's blob store, which pages to disk.

export const BLOB_FOLD_BYTES = 8 * 1024 * 1024;

/**
 * Read `response` into a Blob, folding chunks every `foldBytes`.
 *
 * `onProgress` receives cumulative bytes received, on every chunk.
 */
export async function readResponseToBlob(response, options = {}) {
  const { type = "application/octet-stream", onProgress, foldBytes = BLOB_FOLD_BYTES } = options;

  // No streaming support (old browsers, and jsdom in some tests): fall back to
  // the buffered read, which is what the whole file used to do.
  if (!response.body || typeof response.body.getReader !== "function") {
    const blob = await response.blob();
    if (onProgress) onProgress(blob.size);
    return blob;
  }

  const reader = response.body.getReader();
  const parts = [];
  let pending = [];
  let pendingBytes = 0;
  let received = 0;

  const fold = () => {
    if (!pending.length) return;
    parts.push(new Blob(pending, { type }));
    pending = [];
    pendingBytes = 0;
  };

  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    pending.push(value);
    pendingBytes += value.byteLength ?? value.length ?? 0;
    received += value.byteLength ?? value.length ?? 0;
    if (onProgress) onProgress(received);
    if (pendingBytes >= foldBytes) fold();
  }
  fold();

  // Blob parts are referenced, not copied, so this last step is cheap.
  return new Blob(parts, { type });
}
