import React from "react";
import { Button } from "@kui/foundations-react";
import { SpinnerGlyph } from "./icons";
import { DEFAULT_PAGE_SIZE, describeDepthLimit } from "../utils/pagination";
import T from "../kui/tokens";

/**
 * The end of the results list: a "Load more" button, and — when paging stops for
 * a reason other than running out of results — one line saying why.
 *
 * A button rather than infinite scroll, deliberately: arriving hits kick off
 * per-hit VLM validation, so scroll-driven loading would fan out validation
 * calls as fast as the user can flick. Each extra page stays an explicit choice.
 *
 * The count, the info icon and the page size all live in MetaBar, above the
 * results: they describe the result set, and up there they stay visible without
 * scrolling to the end of a long list. Only the *stop* is reported here, because
 * that is where it happens.
 */
const LoadMoreFooter = ({
  loaded = 0,
  total = null,
  hasMore = false,
  isLoading = false,
  reason = null,
  pageSize = DEFAULT_PAGE_SIZE,
  onLoadMore,
}) => {
  // Gated on paging having actually stopped: "you can only reach 225" reads
  // oddly next to a live Load more button. MetaBar's icon carries the standing
  // explanation for anyone who wants it earlier.
  const stopped = !hasMore ? describeDepthLimit(reason, { total, pageSize }) : null;
  if (!loaded) return null;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: "10px",
        padding: "28px 0 8px",
      }}
    >
      {hasMore && (
        <Button kind="secondary" color="neutral" size="small" onClick={onLoadMore} disabled={isLoading}>
          {isLoading ? (
            <>
              <SpinnerGlyph width={16} height={16} style={{ animation: "esSpin .8s linear infinite" }} />
              <span>Loading…</span>
            </>
          ) : (
            <span>Load more</span>
          )}
        </Button>
      )}

      {stopped && (
        <div style={{ fontSize: "12px", color: T.textSecondary, maxWidth: 460, textAlign: "center" }}>
          {stopped.summary}
        </div>
      )}
    </div>
  );
};

export default LoadMoreFooter;
