import React, { useCallback, useEffect, useRef, useState } from "react";
import { Button, Popover } from "@kui/foundations-react";
import { InfoGlyph } from "./icons";
import { describeDepthLimit } from "../utils/pagination";
import T from "../kui/tokens";

// How long the panel survives the pointer leaving, so it can be crossed into.
// Long enough to traverse the gap between the icon and the panel; short enough
// that a pointer merely passing over the icon does not leave a panel behind.
const CLOSE_DELAY_MS = 180;

/**
 * Info icon explaining why a search caps out where it does, and which setting
 * lifts the cap.
 *
 * Shown beside the running count from the first page onward, not just once
 * paging stops: "showing 20 of 200" against a corpus of millions is exactly when
 * a user needs to know the 200 is a ceiling and is raisable — discovering it
 * after nine clicks of Load more is too late to be useful.
 *
 * Still renders nothing when there is genuinely nothing to explain (the results
 * ran out), so it stays a signal rather than permanent furniture.
 *
 * A Popover, not a Tooltip. The panel holds a button, and a tooltip is a
 * `popover="hint"`: the browser closes it the moment the pointer leaves the
 * trigger, so its content can never be reached. Hover still opens it — the
 * explanation should not cost a click — but it now stays while the pointer is
 * over the panel, and a click pins it open.
 */
const DepthLimitInfo = ({ reason, total = null, pageSize = null, onOpenScoring }) => {
  const [open, setOpen] = useState(false);
  const closeTimer = useRef(null);

  const cancelClose = useCallback(() => {
    if (closeTimer.current) {
      clearTimeout(closeTimer.current);
      closeTimer.current = null;
    }
  }, []);

  const openNow = useCallback(() => {
    cancelClose();
    setOpen(true);
  }, [cancelClose]);

  // Deferred rather than immediate: the pointer has to cross the gap between the
  // icon and the panel, and closing on the way would make the button unreachable
  // — which is the whole bug this replaced.
  const scheduleClose = useCallback(() => {
    cancelClose();
    closeTimer.current = setTimeout(() => setOpen(false), CLOSE_DELAY_MS);
  }, [cancelClose]);

  useEffect(() => cancelClose, [cancelClose]);

  const described = describeDepthLimit(reason, { total, pageSize });
  if (!described) return null;

  const { detail, control } = described;
  // Only offer the shortcut for limits raised in the scoring panel, and only when
  // the parent wired one up — LoadMoreFooter stays usable standalone, so this
  // degrades to naming the control in text rather than breaking.
  const canOpen = control?.action === "openScoring" && typeof onOpenScoring === "function";

  const content = (
    <div style={{ maxWidth: 300, display: "flex", flexDirection: "column", gap: 8 }}>
      <div style={{ fontSize: 12, lineHeight: 1.45 }}>{detail}</div>

      {control && (
        <div style={{ fontSize: 11.5, color: T.textMuted, lineHeight: 1.45 }}>
          {control.panel} → {control.section} → <strong>{control.field}</strong>
          {control.max ? ` (up to ${control.max.toLocaleString()})` : ""}
        </div>
      )}

      {canOpen && (
        <Button
          kind="secondary"
          color="neutral"
          size="tiny"
          onClick={() => {
            setOpen(false);
            onOpenScoring();
          }}
        >
          Open {control.panel}
        </Button>
      )}
    </div>
  );

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
      slotContent={content}
      side="top"
      // On the panel itself, not on the content inside it: the panel has its own
      // padding, and handlers on an inner div would leave that rim dead — the
      // pointer would sit visibly on the popover while the close timer ran out.
      onMouseEnter={openNow}
      onMouseLeave={scheduleClose}
    >
      {/* A button, not a bare svg: it has to be reachable by keyboard, and the
          panel is the only place the remedy appears. The label has to read
          correctly before paging stops as well as after, so it asks about the
          cap rather than about running out. */}
      <button
        type="button"
        aria-label="Why is the number of results limited?"
        onMouseEnter={openNow}
        onMouseLeave={scheduleClose}
        onFocus={openNow}
        style={{
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          padding: 0,
          margin: 0,
          border: "none",
          background: "none",
          color: T.textMuted,
          cursor: "pointer",
          lineHeight: 0,
        }}
      >
        <InfoGlyph width={13} height={13} />
      </button>
    </Popover>
  );
};

export default DepthLimitInfo;
