// State hygiene for switching the selected server (index).
//
// Property-token params embed USD property KEYS from the index they were
// built against ("vehicle_make=Toyota", "physics:rigidBodyEnabled=") — on a
// different index those keys may not exist, so a stale token silently
// zero-matches and the user sees an inexplicably empty result set with no
// offending chip semantics. Everything else in searchParams is portable:
// file/name/path/date/size/user filters, the cutoff, and the bbox dimension
// bounds (bounding boxes are corpus-agnostic base fields on every index).

// The params whose values are index-specific property tokens.
export const INDEX_SPECIFIC_PARAMS = [
  "filter_by_properties",
  "filter_by_properties_include_any",
  "exclude_filter_by_properties",
  "filter_by_properties_numeric",
  "filter_by_properties_version",
];

/**
 * Build the searchParams patch that clears index-specific filter tokens.
 * Pure: returns { patch, prunedKeys } and mutates nothing. prunedKeys lists
 * the params that actually carried a value (for provenance-ref cleanup).
 */
export function pruneIndexFilters(searchParams) {
  const patch = {};
  const prunedKeys = [];
  for (const key of INDEX_SPECIFIC_PARAMS) {
    if (searchParams[key]) {
      patch[key] = "";
      prunedKeys.push(key);
    }
  }
  return { patch, prunedKeys };
}

/**
 * Re-key a scoring config's vector_fields to the index's embedding field.
 * Pure. Returns the config unchanged when the index advertises no field.
 */
export function alignVectorFields(scoringConfig, embeddingConfig) {
  if (!embeddingConfig?.field_name) return scoringConfig;
  return {
    ...scoringConfig,
    vector_fields: {
      [embeddingConfig.field_name]: {
        enabled: true,
        weight: 1.0,
        field_name: embeddingConfig.field_name,
        dimension: embeddingConfig.dimension || 1024,
      },
    },
  };
}

/**
 * Per-index runtime capability from /config.js: the gateway answers 501 on
 * /download for indexes whose corpus storage isn't reachable
 * (`features.download` in the registry). Default is ENABLED — only an
 * explicit `false` hides the affordances — so env-configured single-backend
 * deployments (no runtime mapping, no features block) are unaffected.
 */
export function indexAllowsDownload(serverMapping, serverKey) {
  return serverMapping?.[serverKey]?.features?.download !== false;
}
