// Bridge between the left filter rail and the structured server-side search
// params. A rail click is NOT client-side faceting — it writes a real
// /search_hybrid filter token into searchParams (the same params the Advanced
// drawer edits and the chips display), so the search re-runs server-side, just
// like an LLM-parsed filter.
//
// The exact USD property key is deployment-configurable (env overrides like
// USDSEARCH_SEARCH_LLM_RIGID_BODY_PROPERTY), so the rail learns the *resolved*
// key from the catalog (GET /llm_parse/fields, which now advertises each
// field's `kind` + resolved `property`) instead of hardcoding it.
//
// Token formats mirror the backend builders in nl_parse/fields.py exactly, so
// rail-set tokens are indistinguishable from LLM-parsed ones:
//   property_exists  -> filter_by_properties           "<prop>="
//   property_numeric -> filter_by_properties_numeric   "<prop>>=N" / "<prop><=N"
//   property_match   -> filter_by_properties_include_any "<prop>=~*Class*" (OR)
//   bbox             -> max_bbox_x/y/z = N

import { mergeCsv } from "./llmParse";
import { getUsdProp } from "./assetFacets";

const splitCsv = (s) =>
  String(s || "")
    .split(",")
    .map((t) => t.trim())
    .filter(Boolean);

const escapeRegExp = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// Serialize a rail value the way the backend's _numeric_fragment does: a whole
// number has no decimal point (">=10", not ">=10.0"). Rail controls are
// integer-stepped, so this round-trips losslessly.
const numStr = (value) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return null;
  return Number.isInteger(n) ? String(n) : String(n);
};

// The property key portion of a numeric token ("physics:mass>=10" -> "physics:mass").
const numericTokenKey = (token) => {
  const m = String(token).match(/^(.*?)(<=|>=|<|>|=)/);
  return m ? m[1] : String(token);
};

// --- catalog lookup --------------------------------------------------------

/** The catalog entry for `name`, or null. */
export function getCatalogField(availableFilters, name) {
  if (!Array.isArray(availableFilters)) return null;
  return availableFilters.find((f) => f && f.name === name) || null;
}

/** Resolved USD property key for a property-backed rail field, or null. */
export function railFieldProperty(availableFilters, name) {
  const f = getCatalogField(availableFilters, name);
  return f && f.property ? f.property : null;
}

/** True when the deployment catalog advertises `name`. */
export function catalogHasField(availableFilters, name) {
  return getCatalogField(availableFilters, name) != null;
}

// --- boolean (property_exists) --------------------------------------------

/** Add/remove the existence token `prop=` in filter_by_properties. */
export function buildBoolPatch(prop, checked, params = {}) {
  const token = `${prop}=`;
  const current = params.filter_by_properties;
  const value = checked
    ? mergeCsv(current, token)
    : splitCsv(current)
        .filter((t) => t !== token)
        .join(",");
  return { filter_by_properties: value };
}

/** Whether `prop=` is present in filter_by_properties. */
export function readBool(params = {}, prop) {
  if (!prop) return false;
  return splitCsv(params.filter_by_properties).includes(`${prop}=`);
}

// --- numeric (property_numeric) -------------------------------------------

/**
 * Set a single numeric bound for `prop` in filter_by_properties_numeric.
 * `op` is ">=" (min) or "<=" (max). Removes any prior token for the same
 * property (latest-wins, so dragging the slider overwrites rather than stacks);
 * value <= 0 clears it.
 */
export function buildNumericPatch(prop, op, value, params = {}) {
  const kept = splitCsv(params.filter_by_properties_numeric).filter(
    (t) => numericTokenKey(t) !== prop
  );
  const n = numStr(value);
  if (n != null && Number(value) > 0) kept.push(`${prop}${op}${n}`);
  return { filter_by_properties_numeric: kept.join(",") };
}

/** The numeric value set for `prop` (any operator), or 0 when unset. */
export function readNumeric(params = {}, prop) {
  if (!prop) return 0;
  const re = new RegExp(`^${escapeRegExp(prop)}(?:<=|>=|<|>|=)(.+)$`);
  for (const t of splitCsv(params.filter_by_properties_numeric)) {
    const m = t.match(re);
    if (m) {
      const n = Number(m[1]);
      return Number.isFinite(n) ? n : 0;
    }
  }
  return 0;
}

// --- bbox (dimension) ------------------------------------------------------

/** Set/clear the equal-on-all-axes max bbox bound (dimension <= N meters). */
export function buildBboxMaxPatch(value) {
  const n = Number(value);
  if (Number.isFinite(n) && n > 0) {
    return { max_bbox_x: n, max_bbox_y: n, max_bbox_z: n };
  }
  return { max_bbox_x: "", max_bbox_y: "", max_bbox_z: "" };
}

/** The dimension bound when all three max axes are equal + set, else 0. */
export function readBboxMax(params = {}) {
  const x = params.max_bbox_x;
  const y = params.max_bbox_y;
  const z = params.max_bbox_z;
  if (x === "" || x == null) return 0;
  if (String(x) === String(y) && String(y) === String(z)) {
    const n = Number(x);
    return Number.isFinite(n) ? n : 0;
  }
  return 0;
}

// --- catalog-driven rail groups ---------------------------------------------
//
// The rail's property controls are GENERATED from the deployment's field
// catalog (GET /llm_parse/fields): every property-backed field becomes a
// control by its map.kind, grouped by the catalog's optional `group` key.
// Nothing about which filters exist lives in the frontend anymore — a
// deployment regenerates its catalog against its own index (any corpus:
// isaac, simready, pdp, …) and the rail follows.
//
//   property_match    -> multi-select value facet (OR across checked values)
//   property_exists   -> boolean toggle ("prop=" existence token)
//
// Numeric (property_numeric) and bbox fields deliberately get NO rail control
// (sliders were dropped by design): they stay reachable through natural-
// language queries and the Advanced drawer's raw fields.
//
// Controls are corpus-gated: a facet needs a non-empty value vocabulary and a
// toggle needs the corpus to actually carry its property (stats endpoint), so
// a catalog field the index lacks never renders a dead control.

/**
 * How many corpus assets carry a USD property `key`, from the
 * GET /search/stats/usd_properties `unique_keys` aggregation (0 when absent).
 * Lets the rail gate a control on whether the corpus actually has the property —
 * a deployment can advertise a filter field whose index carries no such assets.
 * Returns 0 when stats are unavailable; callers decide the fallback.
 */
export function corpusPropertyCount(propertiesData, key) {
  if (!key || !propertiesData || !Array.isArray(propertiesData.unique_keys)) return 0;
  const hit = propertiesData.unique_keys.find((k) => k && k.key === key);
  return hit ? Number(hit.asset_count) || 0 : 0;
}

/**
 * The corpus-wide value vocabulary for one property, pivoted from the
 * GET /search/stats/usd_properties `kv_pairs` aggregation. Returns
 * [{value, count}] sorted by count desc (ties: value asc). This is the full
 * superset of selectable values — independent of the current results page.
 */
export function buildCategoryVocab(propertiesData, propertyKey) {
  if (!propertyKey || !propertiesData || !Array.isArray(propertiesData.kv_pairs)) return [];
  return propertiesData.kv_pairs
    .filter((p) => p && p.key === propertyKey && p.value != null && p.value !== "")
    .map((p) => ({ value: String(p.value), count: Number(p.asset_count) || 0 }))
    .sort((a, b) => b.count - a.count || a.value.localeCompare(b.value));
}

// --- enumerated multi-select (property_match, OR) --------------------------

/**
 * Add/remove a contains-match for one categorical value in
 * filter_by_properties_include_any (OR across the selected values). Despite the
 * `Class`/`classes` names this is generic over any categorical facet property
 * (object_class, pdp:Category:Value, …) — the caller passes the property key.
 */
export function buildClassPatch(prop, className, on, params = {}) {
  const token = `${prop}=~*${className}*`;
  const current = params.filter_by_properties_include_any;
  const value = on
    ? mergeCsv(current, token)
    : splitCsv(current)
        .filter((t) => t !== token)
        .join(",");
  return { filter_by_properties_include_any: value };
}

/** The set of class values currently selected for `prop`. */
export function readClasses(params = {}, prop) {
  const out = new Set();
  if (!prop) return out;
  const re = new RegExp(`^${escapeRegExp(prop)}=~\\*(.*)\\*$`);
  for (const t of splitCsv(params.filter_by_properties_include_any)) {
    const m = t.match(re);
    if (m) out.add(m[1]);
  }
  return out;
}

// --- rail-group construction (pure; see the catalog-driven note above) ------

export const DEFAULT_RAIL_GROUP = "USD Properties";
export const RAIL_KINDS = new Set(["property_match", "property_exists"]);

/** "field_name" -> "Field name" (fallback when the catalog sets no label). */
const humanize = (name) =>
  String(name || "")
    .replace(/[_:]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^./, (c) => c.toUpperCase());

const isTruthyBool = (v) => {
  if (v === true) return true;
  const s = String(v ?? "").trim().toLowerCase();
  return s === "true" || s === "1" || s === "yes";
};

/**
 * Build the rail's control groups from the deployment catalog + corpus stats.
 *
 * @param availableFilters the GET /llm_parse/fields payload (or null)
 * @param propertiesData   the GET /search/stats/usd_properties payload (or null)
 * @param hits             the current result page (page-derived fallbacks/bounds)
 * @returns [{ group, controls: [...] }] — groups in catalog first-seen order,
 *          gated controls and empty groups dropped. Controls are UNBOUND (no
 *          checked/onToggle); bindRailControl attaches live state per render.
 */
export function buildRailGroups(availableFilters, propertiesData, hits = []) {
  if (!Array.isArray(availableFilters)) return [];
  const statsLoaded = !!(propertiesData && Array.isArray(propertiesData.unique_keys));
  const groups = new Map(); // name -> controls[], insertion-ordered

  const push = (groupName, control) => {
    const g = groupName || DEFAULT_RAIL_GROUP;
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push(control);
  };

  for (const f of availableFilters) {
    if (!f || !RAIL_KINDS.has(f.kind)) continue;
    if (!f.property) continue; // older backend without resolved property keys
    const label = f.label || humanize(f.name);

    if (f.kind === "property_match") {
      // Corpus-wide vocabulary; falls back to values observed on the current
      // page when stats are unavailable (aggregations disabled).
      let values = buildCategoryVocab(propertiesData, f.property);
      if (values.length === 0) {
        const counts = {};
        hits.forEach((h) => {
          const v = getUsdProp(h, f.property);
          const s = v == null ? "" : String(v).trim();
          if (s) counts[s] = (counts[s] || 0) + 1;
        });
        values = Object.keys(counts)
          .map((v) => ({ value: v, count: counts[v] }))
          .sort((a, b) => b.count - a.count || a.value.localeCompare(b.value));
      }
      if (values.length === 0) continue;
      push(f.group, { kind: "facet", name: f.name, label, property: f.property, values });
      continue;
    }

    // property_exists: gate on the corpus carrying the property (stats);
    // fall back to catalog-only when stats are unavailable.
    const corpusCount = corpusPropertyCount(propertiesData, f.property);
    if (statsLoaded && corpusCount === 0) continue;
    const pageCount = hits.filter((h) => isTruthyBool(getUsdProp(h, f.property))).length;
    push(f.group, {
      kind: "toggle",
      name: f.name,
      label,
      property: f.property,
      count: statsLoaded ? corpusCount : pageCount,
    });
  }

  return Array.from(groups.entries())
    .filter(([, controls]) => controls.length > 0)
    .map(([group, controls]) => ({ group, controls }));
}

/**
 * Attach live selection state + write-through handlers to one control.
 * Called at render time against the CURRENT searchParams (never memoized with
 * the group construction, which deliberately excludes searchParams).
 */
export function bindRailControl(control, searchParams = {}, { applyRailPatch }) {
  switch (control.kind) {
    case "facet": {
      const selected = readClasses(searchParams, control.property);
      return {
        ...control,
        options: control.values.map((v) => ({
          value: v.value,
          label: v.value,
          count: v.count,
          checked: selected.has(v.value),
          dimmed: v.count === 0 && !selected.has(v.value),
          onToggle: () =>
            applyRailPatch(buildClassPatch(control.property, v.value, !selected.has(v.value), searchParams)),
        })),
      };
    }
    case "toggle": {
      const checked = readBool(searchParams, control.property);
      return {
        ...control,
        checked,
        onToggle: () => applyRailPatch(buildBoolPatch(control.property, !checked, searchParams)),
      };
    }
    default:
      return control;
  }
}
