// Keys that are always present but are not user-facing filters — paging, the
// search method, and the internal API response knobs that are pinned to their
// defaults (return_images/metadata/tags = true, root_prims/predictions = false).
// These must be excluded: return_images & co. are always `true`, so counting
// them would make hasActiveFilters permanently true (and, via computeIsLanding,
// make the landing page unreachable). A search with only these set is pristine.
const NON_FILTER_KEYS = new Set([
  "limit",
  "embedding_knn_search_method",
  "bbox_use_scaled_dimensions",
  "return_images",
  "return_metadata",
  "return_tags",
  "return_root_prims",
  "return_predictions",
]);

/**
 * Whether `searchParams` carries any user-set filter — i.e. the user is
 * deliberately searching, even with an empty search bar (a filter-only search).
 * Used both to enable the empty-bar submit and to keep such searches anchored in
 * the results view (see computeIsLanding) and restored on reload (deserialize).
 *
 * `fileExtensionDefault` / `cutoffDefault` are the app's defaults for
 * `file_extension_include` / `cutoff_threshold`; those keys are always present
 * and only count as active when changed from their default (or cleared).
 */
export function computeHasActiveFilters(searchParams, fileExtensionDefault, cutoffDefault = "") {
  return Object.entries(searchParams || {}).some(([key, value]) => {
    if (NON_FILTER_KEYS.has(key)) return false;
    if (key === "file_extension_include") return value !== fileExtensionDefault && value !== "";
    if (key === "cutoff_threshold") return value !== cutoffDefault && value !== "";
    if (typeof value === "boolean") return value === true; // e.g. deduplicate_by_hash
    return value !== "" && value !== null && value !== undefined;
  });
}
